def largest_k_multiple_free_subset_size(n, k, numbers):
    numbers.sort()
    dp = [1] * n
    for i in range(1, n):
        j = i - 1
        while j >= 0:
            if numbers[i] % numbers[j] == 0 and numbers[i] // numbers[j] > 1:
                dp[i] = max(dp[i], dp[j] + 1)
            elif numbers[i] % numbers[j] != 0:
                break
            j -= 1
    return max(dp)

