def max_k_multiple_free_subset_size(n, k, arr):
    arr.sort()
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] % arr[j] == 0 and arr[i] // arr[j] == k:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

